def heapify_inplace(arr: list[int]) -> None:
    """Build a min-heap in-place in O(n)."""
    n = len(arr)
    # Start from last internal node, work up to root
    for i in range(n // 2 - 1, -1, -1):
        sift_down(arr, i, n)

def sift_down(arr: list[int], i: int, n: int) -> None:
    smallest = i
    left, right = 2 * i + 1, 2 * i + 2
    if left < n and arr[left] < arr[smallest]:
        smallest = left
    if right < n and arr[right] < arr[smallest]:
        smallest = right
    if smallest != i:
        arr[i], arr[smallest] = arr[smallest], arr[i]
        sift_down(arr, smallest, n)

arr = [5, 3, 8, 1, 9, 2, 7]
heapify_inplace(arr)
print(arr)  # [1, 3, 2, 5, 9, 8, 7]  — valid min-heap

def heap_pop(heap: list[int]) -> int:
    if len(heap) == 1:
        return heap.pop()
    minimum = heap[0]                 # Step 1: record the answer
    heap[0] = heap.pop()             # Step 2: move last to root
    _sift_down(heap, 0, len(heap))
    return minimum

def _sift_down(heap: list[int], i: int, n: int) -> None:
    while True:
        smallest = i
        left, right = 2 * i + 1, 2 * i + 2
        if left < n and heap[left] < heap[smallest]:
            smallest = left
        if right < n and heap[right] < heap[smallest]:
            smallest = right
        if smallest == i:
            break                     # heap property satisfied
        heap[i], heap[smallest] = heap[smallest], heap[i]
        i = smallest

heap = [1, 3, 2, 7, 9, 5]
print(heap_pop(heap))   # 1
print(heap)             # [2, 3, 5, 7, 9]  — valid min-heap

import heapq

# Dijkstra's algorithm skeleton — min-heap on (distance, node)
def dijkstra(graph: dict, start: str) -> dict:
    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    heap = [(0, start)]              # (cost, node)

    while heap:
        cost, u = heapq.heappop(heap)   # always processes closest node first
        if cost > dist[u]:
            continue                  # stale entry — skip
        for v, weight in graph[u]:
            new_cost = cost + weight
            if new_cost < dist[v]:
                dist[v] = new_cost
                heapq.heappush(heap, (new_cost, v))
    return dist
